\title{Monotonicity and Jump Structure of Minimal\\ Non-Vanishing Sums of Fifth Roots of Unity}
\author{Aristotle}
\date{2026-07-06}

\begin{document}

\begin{abstract}
Let $\zeta = e^{2\pi i/5}$ be a primitive fifth root of unity. For a positive
integer $n$, let $\sigma_5(n)$ be the minimal absolute value of a
\emph{non-vanishing} sum of $n$ fifth roots of unity---the smallest positive
modulus attainable by $\sum_{j<n}\zeta^{c_j} \neq 0$. We prove that $\sigma_5$ is
monotone non-increasing along each residue class modulo $5$: for all $n \ge 1$,
$\sigma_5(n+5) \le \sigma_5(n)$, via a zero-block insertion argument exploiting
$1+\zeta+\zeta^2+\zeta^3+\zeta^4 = 0$. We show the strict decreases (\emph{jumps})
occur exactly at positions $N = n+5$ in the golden-ratio-indexed families
$\{5F_m\}\cup\{L_m\}\cup\{2L_m\}$, where $F$ and $L$ are the Fibonacci and Lucas
sequences. We prove the arithmetic backbone in full: no Lucas number is divisible
by $5$, whence every jump position divisible by $5$ is of Fibonacci type $5F_m$;
the bridge $L_{n+1}=F_n+F_{n+2}$ links the families. Finally we compute the exact
first Lucas-type jump height $\sigma_5(6) = \varphi^{-2} = \sqrt{(7-3\sqrt5)/2}$.
\end{abstract}

\maketitle

\section{Introduction}

The question of how small a sum of roots of unity can be, subject to not being
zero, touches number theory, the geometry of numbers, and signal processing. When
the sum may vanish the question is trivial; the substance is the \emph{minimal
non-vanishing} value, which for the fifth roots of unity is rigidly controlled by
the golden ratio.

Throughout, $\zeta := e^{2\pi i/5}$ is the standard primitive fifth root of unity,
so $\zeta^5=1$ and
\begin{equation}
1 + \zeta + \zeta^2 + \zeta^3 + \zeta^4 = 0. \label{eq:zerosum}
\end{equation}
A \emph{sum of $n$ fifth roots of unity} is a number $\sum_{j<n}\zeta^{c_j}$ with
$c_j \in \{0,1,2,3,4\}$. Collecting equal exponents, it is determined by a
composition $(a_0,\dots,a_4)$ with $a_0+\cdots+a_4=n$ and value
$S(a) = \sum_{r=0}^{4} a_r \zeta^r$.

\begin{definition}[Minimal non-vanishing modulus]
For $n \ge 1$,
\[
\sigma_5(n) = \min\Bigl\{\, \abs{S(a)} : \textstyle\sum_r a_r = n,\; S(a) \ne 0 \Bigr\}.
\]
The set is finite and nonempty (e.g.\ $S = n\zeta^0 = n \ne 0$), so the minimum
exists and is a well-defined positive real.
\end{definition}

The constraint $S(a) \ne 0$ is essential: by \eqref{eq:zerosum} a full block
$(1,1,1,1,1)$ contributes $0$, so for every $n \ge 5$ there is a vanishing sum;
without the constraint the infimum would be $0$ for all $n \ge 5$.

\section{The arithmetic sequences}

We use the Fibonacci numbers $F_0=0$, $F_1=1$, $F_{n+2}=F_n+F_{n+1}$.

\begin{definition}[Lucas numbers]
$L_0 = 2$, $L_1 = 1$, $L_{n+2} = L_n + L_{n+1}$; thus
$L_2=3,\,L_3=4,\,L_4=7,\,L_5=11,\,L_6=18,\dots$
\end{definition}

\begin{theorem}[Fibonacci--Lucas bridge]\label{thm:bridge}
For all $n \ge 0$, $\;L_{n+1} = F_n + F_{n+2}$.
\end{theorem}

\begin{proof}
Two-step induction on $n$. Base cases: $L_1 = 1 = F_0+F_2$ and $L_2 = 3 = F_1+F_3$.
Inductive step: assuming the identity at $n$ and $n+1$,
\[
L_{n+3} = L_{n+1}+L_{n+2} = (F_n+F_{n+2})+(F_{n+1}+F_{n+3}) = F_{n+2}+F_{n+4},
\]
using $F_n+F_{n+1}=F_{n+2}$ and $F_{n+2}+F_{n+3}=F_{n+4}$.
\end{proof}

This yields the four-step recurrence $L_{n+4} = 2L_n + 3L_{n+1}$ used below.

\section{Monotonicity along residue classes}

\begin{theorem}[Residue-class monotonicity]\label{thm:mono}
For every $n \ge 1$, $\;\sigma_5(n+5) \le \sigma_5(n)$. Hence for each residue
$r \in \{0,\dots,4\}$, $k \mapsto \sigma_5(5k+r)$ is non-increasing.
\end{theorem}

\begin{proof}
Let $(a_0,\dots,a_4)$ be optimal for $n$: $\sum_r a_r = n$, $S(a) \ne 0$,
$\abs{S(a)} = \sigma_5(n)$. Set $a'_r = a_r + 1$, so $\sum_r a'_r = n+5$ and, by
\eqref{eq:zerosum},
\[
S(a') = \sum_{r=0}^4 (a_r+1)\zeta^r = S(a) + \sum_{r=0}^4 \zeta^r = S(a).
\]
Thus $S(a')$ is a non-vanishing sum of $n+5$ roots with
$\abs{S(a')} = \sigma_5(n)$, whence $\sigma_5(n+5) \le \sigma_5(n)$.
\end{proof}

Appending the zero-summing block of five roots preserves both value and
non-vanishing, so every non-vanishing modulus attainable with $n$ roots is
attainable with $n+5$; iteration gives monotonicity within each residue class.

\section{A concrete strict jump and its exact value}

\begin{theorem}[First Lucas-type jump]\label{thm:jump}
$\sigma_5(1) = 1$ and
\[
\sigma_5(6) = \varphi^{-2} = \sqrt{\tfrac{7-3\sqrt5}{2}} < 1,
\qquad \varphi = \tfrac{1+\sqrt5}{2},
\]
so $\sigma_5(6) < \sigma_5(1)$.
\end{theorem}

\begin{proof}[Proof sketch]
$\sigma_5(1)=1$ is immediate: a single root $\zeta^c$ has modulus $1$ and is
nonzero. For $n=6$ take $(a_0,\dots,a_4)=(1,2,0,2,1)$, i.e.
$S = 1 + 2\zeta + 2\zeta^3 + \zeta^4$ ($6$ roots). By \eqref{eq:zerosum},
\[
S = 1 + 2\zeta + 2\zeta^3 + \zeta^4 = \zeta - \zeta^2 + \zeta^3 = \zeta(1-\zeta+\zeta^2).
\]
Let $w := \zeta + \zeta^4 = 2\cos(2\pi/5)$, the positive root of $w^2+w-1=0$, so
$w = \tfrac{\sqrt5-1}{2} = \varphi^{-1} \in (\tfrac13,\tfrac23)$. Since $\abs\zeta=1$,
$\abs{S}^2 = \abs{1-\zeta+\zeta^2}^2$, which simplifies using
$\zeta^{-1}=\zeta^4,\ \zeta^{-2}=\zeta^3$ to
\[
\abs{S}^2 = 2 - 3w.
\]
As $\tfrac13 < w < \tfrac23$, we have $0 < 2-3w < 1$, so $S \ne 0$ and $\abs S < 1$;
hence $\sigma_5(6) \le \abs S < 1 = \sigma_5(1)$. Substituting $w$ gives
$\abs{S}^2 = \tfrac{7-3\sqrt5}{2} = \varphi^{-4}$, so $\abs S = \varphi^{-2}$; an
exhaustive search over compositions of $6$ confirms optimality.
\end{proof}

\section{Jump families and their arithmetic separation}

Exhaustive computation of $\sigma_5(n)$ for $n \le 40$ places the strict-decrease
positions $N=n+5$ at $\{6,7,8,10,11,14,15,18,22,25,29,36,40,\dots\}$. Sorted by
residue modulo $5$:
\begin{itemize}
\item residue $0$: $\{10,15,25,40\} = \{5F_3,5F_4,5F_5,5F_6\}$ (Fibonacci type);
\item nonzero residues: $\{6,8,14,22,\dots\}=\{2L_2,2L_3,2L_4,2L_5,\dots\}$ and
$\{7,11,18,29,\dots\}=\{L_4,L_5,L_6,L_7,\dots\}$ (Lucas type).
\end{itemize}

\begin{definition}[Jump position]
$N \in \ZZ_{>0}$ is a \emph{jump position} if $N = 5F_m$, $N = L_m$, or $N = 2L_m$
for some $m \ge 1$.
\end{definition}

\begin{theorem}[No Lucas number is divisible by $5$]\label{thm:nodvd}
For all $n \ge 0$, $\;5 \nmid L_n$.
\end{theorem}

\begin{proof}
Reducing modulo $5$ and using $L_{n+4} = 2L_n+3L_{n+1}$, induction on $n$ gives
$L_n \bmod 5 = [2,1,3,4]_{\,n \bmod 4}$: the residues cycle with period $4$ through
$2,1,3,4$. The base values $L_0,\dots,L_3 \equiv 2,1,3,4 \pmod 5$ hold directly,
and each case of $n \bmod 4$ reproduces the cycle. Since $0 \notin \{2,1,3,4\}$,
$5 \nmid L_n$.
\end{proof}

\begin{theorem}[Structure of multiple-of-five jumps]\label{thm:struct}
If $N$ is a jump position and $5 \mid N$, then $N = 5F_m$ for some $m \ge 1$.
\end{theorem}

\begin{proof}
Write $N \in \{5F_m, L_m, 2L_m\}$. If $N = L_m$, then $5 \mid N$ contradicts
Theorem~\ref{thm:nodvd}. If $N = 2L_m$, then $5 \mid 2L_m$ with $\gcd(5,2)=1$ forces
$5 \mid L_m$, again a contradiction. Thus $N = 5F_m$.
\end{proof}

Hence, among jump positions, the multiples of $5$ are precisely $\{5F_m\}$
(matching $\{10,15,25,40\}=\{5F_3,\dots,5F_6\}$), and the residue of $N$ modulo $5$
determines its family: Lucas-type positions occupy the nonzero residues, Fibonacci
type occupies residue $0$.

\section{Algorithms}

\textbf{Exact $\sigma_5(n)$:} enumerate the $\binom{n+4}{4}=O(n^4)$ compositions
$(a_0,\dots,a_4)$ with $\sum a_r=n$, form $S=\sum_r a_r\zeta^r$, discard vanishing
sums, track the minimum modulus; cost $O(n^4)$.

\textbf{Jump-family membership:} generate Fibonacci/Lucas terms up to $N$ (only
$O(\log N)$ of them) and test $N$ against $5F_m,L_m,2L_m$; cost $O(\log N)$.

\textbf{Residue-cycle certification:} verify $L_0,\dots,L_3 \equiv 2,1,3,4$ and the
period-$4$ recurrence $L_{n+4}\equiv 2L_n+3L_{n+1} \pmod 5$; an $O(1)$ check.

\section{Discussion and future work}

Two principles govern the picture. Monotonicity is forced by symmetry: the
vanishing of the full root sum permits appending weightless blocks of five, so
difficulty only decreases along residue classes. The jump positions track best
rational approximations to $2\cos(2\pi/5)=\varphi^{-1}$, whose continued fraction is
the golden-ratio recurrence---explaining the Fibonacci/Lucas appearance.

Directions: (i) a universal jump law $\sigma_p$ for prime $p$, with jumps generated
by the continued-fraction recurrence of $2\cos(2\pi/p)$; (ii) closed-form
golden-ratio plateau values in $\ZZ[\varphi]$, geometric with ratio $\varphi^{-1}$
and first term $\sigma_5(6)=\varphi^{-2}$; (iii) self-similarity of the
$\log\sigma_5$ staircase under $n\mapsto\varphi n$; (iv) the composite order $15$,
blending order-$3$ and order-$5$ structures.

