from __future__ import annotations
import cmath
from typing import Dict, List, Optional, Tuple

W5 = cmath.exp(2j * cmath.pi / 5)

def sigma5(n: int, tol: float = 1e-9) -> Optional[float]:
    if n <= 0:
        return None
    best: Optional[float] = None
    for a0 in range(n + 1):
        for a1 in range(n + 1 - a0):
            for a2 in range(n + 1 - a0 - a1):
                for a3 in range(n + 1 - a0 - a1 - a2):
                    a4 = n - a0 - a1 - a2 - a3
                    s = a0 + a1*W5 + a2*W5**2 + a3*W5**3 + a4*W5**4
                    m = abs(s)
                    if m > tol and (best is None or m < best):
                        best = m
    return best

def verify_monotonicity(nmax: int = 30) -> None:
    """Print sigma5 along each residue class mod 5 and confirm non-increase."""
    table: Dict[int, float] = {n: sigma5(n) for n in range(1, nmax + 1)}  # type: ignore
    for r in range(5):
        seq: List[Tuple[int, float]] = sorted((n, v) for n, v in table.items() if n % 5 == r)
        ok = all(seq[i][1] >= seq[i+1][1] - 1e-9 for i in range(len(seq)-1))
        chain = "  >=  ".join(f"{v:.4f}" for _, v in seq)
        print(f"r={r}: {chain}   [{'OK' if ok else 'FAIL'}]")

if __name__ == "__main__":
    verify_monotonicity()

