def lucas(n: int) -> int:
    a, b = 2, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def match_jumps(nmax: int = 35) -> None:
    """Check strict decreases sigma5(n) > sigma5(n+5) match {5F_m,L_m,2L_m}."""
    table: Dict[int, float] = {n: sigma5(n) for n in range(1, nmax + 1)}  # type: ignore
    fam: Dict[int, str] = {}
    for m in range(1, 12):
        fam[5*fib(m)] = f"5F_{m}"
        fam[lucas(m)] = f"L_{m}"
        fam[2*lucas(m)] = f"2L_{m}"
    for n in range(1, nmax - 4):
        is_jump = table[n] > table[n+5] + 1e-9
        pos = n + 5
        in_fam = pos in fam
        if is_jump or in_fam:
            status = "match" if is_jump == in_fam else "MISMATCH"
